return {["fb08_01"]={["dsc"]=[[你走在青泥小道上。左边不远传来阵阵水响，原来那里就是天下知名都江堰。拦河分流，使岷江之水分注到无数小小溪流中，才免了连年的水祸，灌溉出了这富饶的成都平原。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb08_01]],["item1"]=[[fb08item26]],["item2"]=[[ycitem2]],["name"]=[[青泥小道]],["permission"]=1,["right"]=[[fb08_02]],["role1"]=[[fb08r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_03]],["visible"]=1},["fb08_02"]={["dsc"]=[[你走在青石大道上。两边是稀疏的树林和连片的田野。一条条小溪和路平行，溪流清澈见底，水流甚急。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb08_02]],["left"]=[[fb08_01]],["name"]=[[青石大道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_03"]={["down"]=[[fb08_01]],["dsc"]=[[你走在青石大道上。远远传来细细的水声，掩盖在路边密密树林的风声中。望北可以看到一座大山了，苍苍翠翠，象一块清清纯纯的碧玉。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb08_03]],["name"]=[[青石大道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb08_04]],["visible"]=1},["fb08_04"]={["down"]=[[fb08_03]],["dsc"]=[[小桥横跨小溪上。溪水清澈，游鱼卵石斑驳可数。桥北面就是青城建福宫了。青城是道家发轫之处，号道教的“第五洞天”，相传东汉张陵在此结庐传授五斗米道，至今宫阙连绵，传道嗣法不绝。]],["enterable"]=1,["id"]=[[fb08_04]],["item1"]=[[21drtrigger01]],["item2"]=[[21drtrigger02]],["name"]=[[小桥]],["permission"]=1,["role1"]=[[ever04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_05]],["visible"]=1},["fb08_05"]={["BgmDown"]=1,["down"]=[[fb08_04]],["dsc"]=[[建福宫旧称丈人观，以其座落丈人峰下故也。相传五岳丈人宁封子修道于此。院内树木假山，相互掩映。周围林木苍翠，浓荫蔽日，炎夏来此，十分凉爽。这里也是上山的起点。]],["enterable"]=1,["id"]=[[fb08_05]],["item1"]=[[bfitem1]],["leftUp"]=[[fb08_06]],["name"]=[[建福宫]],["permission"]=1,["role1"]=[[fb08r05_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_06"]={["dsc"]=[[你走在盘山磴道上。山木蔽日，幽静宜人。过了“青城”木牌楼，西上就是天然图画了。东南方向是建福宫。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb08_06]],["item1"]=[[2020qmjs1]],["leftUp"]=[[fb08_07]],["name"]=[[盘山磴道]],["permission"]=1,["rightDown"]=[[fb08_05]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_07"]={["dsc"]=[[这里岩壁矗立，绿树映辉，牌阁在山垭间巍然屹立。四顾峰奇石异，云雾缥缈，远近观赏，如在画中。阁左“天生桥”，一石丈余飞插石壁之间，十分险峻。]],["enterable"]=1,["id"]=[[fb08_07]],["item1"]=[[ycitem6]],["leftUp"]=[[fb08_08]],["name"]=[[天然图画]],["permission"]=1,["rightDown"]=[[fb08_06]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_09]],["visible"]=1},["fb08_08"]={["dsc"]=[[你走在青城山路上。山木蔽日，幽静宜人。西上就是天师洞，东边是天然图画。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb08_08]],["leftUp"]=[[fb08_11]],["name"]=[[青城山路]],["permission"]=1,["rightDown"]=[[fb08_07]],["role1"]=[[fb08r08_1]],["role2"]=[[cfitem1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_09"]={["down"]=[[fb08_07]],["dsc"]=[[驻鹤庄相传为仙人休息赏玩之所。常有成群丹顶鹤栖息、飞鸣于林间。]],["enterable"]=1,["id"]=[[fb08_09]],["item1"]=[[fb08item18]],["item2"]=[[fb08item18]],["item3"]=[[fb08item18]],["name"]=[[驻鹤庄]],["permission"]=2,["role1"]=[[fb08r09_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_10"]={["dsc"]=[[观前古银杏树相传为张天师手植，高可十余丈，腰围七、八人合抱，枝叶扶疏，苍盖如云。]],["enterable"]=1,["id"]=[[fb08_10]],["item1"]=[[fb08item3]],["item2"]=[[mengneiyiyunpcadd]],["name"]=[[古银杏树]],["permission"]=2,["right"]=[[fb08_11]],["role1"]=[[fb08r08_2]],["role2"]=[[fb08r10_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_11"]={["BgmDown"]=1,["dsc"]=[[天师洞以东汉张陵在此讲道修炼而得名，又名古常道观。洞在山腰混元顶下峭壁间。中塑天师像，沿岩壁有廊可通。正殿名三皇殿，重檐回廊，雄踞高台，气势宏伟。内供伏羲、神农、轩辕三皇石刻造像。]],["enterable"]=1,["id"]=[[fb08_11]],["item1"]=[[bfitem3]],["item2"]=[[ycitem5]],["left"]=[[fb08_10]],["name"]=[[天师洞]],["permission"]=1,["right"]=[[fb08_12]],["rightDown"]=[[fb08_08]],["rightUp"]=[[fb08_15]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_14]],["visible"]=1},["fb08_12"]={["dsc"]=[[三岛石上刻“降魔”二字，相传为张天师当年降魔，因巨石当道，挥剑力劈，石裂为三，成为三块相连的岛石。石裂处自然生成石梯。]],["enterable"]=1,["id"]=[[fb08_12]],["item1"]=[[fb08item6]],["left"]=[[fb08_11]],["name"]=[[三岛石]],["permission"]=2,["right"]=[[fb08_13]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_13"]={["dsc"]=[[沿石梯向下，就是海棠溪。这里是溪上的听泉亭，四顾山环水绕，古藤蔓蔓，飞泉溅落池中，如琴弦轻拨，如珠落玉盘，清绝幽绝。]],["enterable"]=1,["id"]=[[fb08_13]],["item1"]=[[fb08item28]],["item2"]=[[cfitem3]],["left"]=[[fb08_12]],["name"]=[[听泉亭]],["permission"]=2,["role1"]=[[fb08r13_2]],["role2"]=[[fb08r13_4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_14"]={["BgmDown"]=1,["down"]=[[fb08_11]],["dsc"]=[[古常道观的中心是三清殿。殿中供奉三清教主:玉清原始天尊、上清灵宝天尊和太清太上老君。原始天尊手拿圆珠，象征洪元。灵宝天尊怀抱太极图，象征混元。太上老君手持扇子，象征太初。殿旁有一对联，著墨极浓。]],["enterable"]=1,["id"]=[[fb08_14]],["item1"]=[[fb08item7]],["item2"]=[[bfitem2]],["name"]=[[三清殿]],["permission"]=2,["role1"]=[[fb08r14_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_15"]={["dsc"]=[[你走在古龙桥上。望见岩壁上一个大裂槽。宽二十余丈深，深达六、七丈，传说是张天师降魔时以笔划山而过的仙家痕迹。]],["enterable"]=1,["id"]=[[fb08_15]],["leftDown"]=[[fb08_11]],["name"]=[[古龙桥]],["permission"]=1,["role1"]=[[fb08r15_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_16]],["visible"]=1},["fb08_16"]={["down"]=[[fb08_15]],["dsc"]=[[祖师殿又名真武宫。祖师殿背靠轩辕峰，面向白云溪，十分清幽。附近轩皇台，相传为黄帝受道处。]],["enterable"]=1,["id"]=[[fb08_16]],["name"]=[[祖师殿]],["permission"]=1,["right"]=[[fb08_17]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_17"]={["BgmDown"]=1,["dsc"]=[[你来到朝阳洞。洞深广数丈，相传是宁封子栖息处。这里也是观日好去处，“古洞常临光照耀”，正是指旭日东升，霞光透过绿荫，射到洞口，一片璀灿绚丽的景色。]],["enterable"]=1,["id"]=[[fb08_17]],["item1"]=[[ycitem1]],["left"]=[[fb08_16]],["name"]=[[朝阳洞]],["permission"]=1,["role1"]=[[fb08r17_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_18]],["visible"]=1},["fb08_18"]={["down"]=[[fb08_17]],["dsc"]=[[山势越来越陡峭，石梯几近壁立，拐过观日亭，远远看到青城山巅，高台山之阳的飞檐流瓦，上清宫到了。]],["enterable"]=1,["id"]=[[fb08_18]],["name"]=[[三湾九倒]],["permission"]=1,["rightUp"]=[[fb08_20]],["role1"]=[[fb08r18_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_19"]={["dsc"]=[[上清殿左有鸳鸯井，一方一圆，泉流暗通。圆者水浊，方者水清。井水一温一凉，昔人题诗曰:“谁知上界神仙客，也与炎凉世态同”。]],["enterable"]=1,["id"]=[[fb08_19]],["item1"]=[[ycitem4]],["item2"]=[[cfitem2]],["name"]=[[鸳鸯井]],["permission"]=2,["right"]=[[fb08_20]],["role1"]=[[fb08r19_1]],["role2"]=[[fb08r19_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_20"]={["dsc"]=[[上清宫是老君道场。宫前山门，矮树搭就，甚为灵动。宫内殿堂古色清雅，正殿供奉太上老君、吕纯阳和张三丰塑像。山前摩崖石刻“天下第五名山”气势浑厚，很是壮观。]],["enterable"]=1,["id"]=[[fb08_20]],["item1"]=[[21maskwp01]],["left"]=[[fb08_19]],["leftDown"]=[[fb08_18]],["leftUp"]=[[fb08_22]],["name"]=[[上清宫]],["permission"]=1,["right"]=[[fb08_21]],["role1"]=[[fb08r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_23]],["visible"]=1},["fb08_21"]={["dsc"]=[[上清殿右是麻姑池，亦称天池。池深数尺，形如半月，水色清澈，四季久雨不盈，长旱不涸。]],["enterable"]=1,["id"]=[[fb08_21]],["item1"]=[[fb08item29]],["item2"]=[[cg2item1]],["left"]=[[fb08_20]],["name"]=[[麻姑池]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_22"]={["BgmDown"]=1,["dsc"]=[[呼应亭高居彭祖峰顶，是青城最高处。登临长啸，余音回荡，众山皆应。看雪岭光腾，红吞沧海，锦江春涨，绿到瀛洲。夏日夜分，有圣灯浮云，传说是神仙朝贺张天师所点仙灯，看来让人感叹不已。]],["enterable"]=1,["id"]=[[fb08_22]],["name"]=[[呼应亭]],["permission"]=2,["rightDown"]=[[fb08_20]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_23"]={["BgmDown"]=1,["down"]=[[fb08_20]],["dsc"]=[[这里是松风观前殿。松风观是青城派总所，青城派威镇川中，以其人才辈出之故。当今掌门人余岳正道长，虽其貌不扬，身形矮小，却是青城一代宗师。殿中左右分列四大天王，手中分执剑、琵琶、伞、蛇四样法器，代表了风调雨顺的凡民宿愿。]],["enterable"]=1,["id"]=[[fb08_23]],["name"]=[[松风观]],["permission"]=1,["role1"]=[[fb08r23_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_24]],["visible"]=1},["fb08_24"]={["down"]=[[fb08_23]],["dsc"]=[[这里是松风观通往后院的中门，门厚三寸，红松铜箍，数十年犹有松香飘荡，和观中香火掺和出一股出世的滋味。外派人士到此就该回头了。]],["enterable"]=1,["id"]=[[fb08_24]],["name"]=[[穿廊门]],["permission"]=2,["role1"]=[[fb08r24_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_26]],["visible"]=1},["fb08_25"]={["dsc"]=[[这间整洁的厢房是给来青城做客、游玩的人们准备的房间，明净透亮的窗户用厚厚的窗纱遮了大半。房里别无他物，只有中间放着一张收拾得舒舒服服的大床，看着就让人想睡觉。青城弟子偶尔也来这里休息。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb08_25]],["name"]=[[客房]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb08_29]],["visible"]=1},["fb08_26"]={["down"]=[[fb08_24]],["dsc"]=[[这里是松风观中连贯前殿后院的走廊，松风观高矗山顶，从走廊望去，青山鸟寂，幽谷风生，漫天薄雾时时弥散在长林翠竹之间。自古号称:“青城天下幽”，不妨在此体味。]],["enterable"]=1,["id"]=[[fb08_26]],["name"]=[[松风走廊]],["permission"]=2,["role1"]=[[fb08r26_1]],["role2"]=[[fb08r26_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_30]],["visible"]=1},["fb08_27"]={["BgmDown"]=1,["dsc"]=[[这是一间干干净净的书房。当中一个大檀木桌，桌上放着不少书籍。靠墙的地方还有一个书架，架上满满的全是各种封装的书。其中不少书看上去古意盎然，显然年代已久。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb08_27]],["item1"]=[[fb08item10]],["item2"]=[[fb08item1000]],["name"]=[[书房]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb08_31]],["visible"]=1},["fb08_28"]={["BgmDown"]=1,["dsc"]=[[这是间整洁的厢房，明净透亮的窗户用厚厚的窗纱遮了大半，光线很昏暗。房里别无他物，只有中间放着一张收拾得舒舒服服的大床，看着就让人想睡觉。看来这里是青城休息的地方。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb08_28]],["item1"]=[[fb08item22]],["item2"]=[[fb08item23]],["name"]=[[厢房]],["permission"]=2,["right"]=[[fb08_29]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_29"]={["down"]=[[fb08_25]],["dsc"]=[[这里是松风观中连贯操练场和西厢的走廊，松风观高矗山顶，从走廊望去，青山鸟寂，幽谷风生，漫天薄雾时时弥散在长林翠竹之间。自古号称:“青城天下幽”，不妨在此体味。这里南边是客房，北边是厨房，西边常常关着门的是本派弟子的练功休息室。]],["enterable"]=1,["id"]=[[fb08_29]],["item1"]=[[ycitem3]],["left"]=[[fb08_28]],["name"]=[[松风西廊]],["permission"]=2,["right"]=[[fb08_30]],["role1"]=[[fb08r29_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_33]],["visible"]=1},["fb08_30"]={["down"]=[[fb08_26]],["dsc"]=[[这里是青城弟子练功习武之所，“冬练三九、夏练三伏”，出家人往往勤快一些，往往天光才有鱼肚白，这里就有练功的影子。到得日出山坳，便是满场的人声了。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb08_30]],["left"]=[[fb08_29]],["name"]=[[练功操场]],["permission"]=2,["right"]=[[fb08_31]],["role1"]=[[fb08r30_2]],["role2"]=[[fb08r30_1]],["role3"]=[[fb08r30_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_34]],["visible"]=1},["fb08_31"]={["down"]=[[fb08_27]],["dsc"]=[[这里是松风观中连贯操练场和东厢的走廊，松风观高矗山顶，从走廊望去，青山鸟寂，幽谷风生，漫天薄雾时时弥散在长林翠竹之间。自古号称:“青城天下幽”，不妨在此体味。这里的南边是书房，北边是兵器室，东边一直关着门的是本派的库房。]],["enterable"]=1,["id"]=[[fb08_31]],["item1"]=[[fb08item8]],["left"]=[[fb08_30]],["name"]=[[松风东廊]],["permission"]=2,["right"]=[[fb08_32]],["role1"]=[[fb08r31_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb08_35]],["visible"]=1},["fb08_32"]={["dsc"]=[[这里是青城一派的库房，收藏着各种途径得来的珍宝。库房北边壁上柜挂着一些白章虎皮、花格豹皮和其它不知名的皮毛，南边壁柜里摆放着一些奇石和铜铁制品，看来还是值点钱的。]],["enterable"]=1,["id"]=[[fb08_32]],["item1"]=[[fb08item12]],["item2"]=[[fb08item13]],["item3"]=[[fb08item14]],["left"]=[[fb08_31]],["name"]=[[库房]],["permission"]=2,["role1"]=[[fb08r32_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_33"]={["down"]=[[fb08_29]],["dsc"]=[[这是青城山的厨房，收拾得异常干净。中央摆着大圆桌，桌上摆着一些点心和茶水，周围则放着几张竹椅。窗口还摆着几盆山野鲜花。平时青城山的弟子和家眷都在这里用餐。]],["enterable"]=1,["id"]=[[fb08_33]],["item1"]=[[fb08item16]],["name"]=[[厨房]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_34"]={["down"]=[[fb08_30]],["dsc"]=[[这里是松风观主殿。殿中陈设奢华，显见青城派财力不菲。正中的三清座像也塑得极为精致，显微着著，甚有神韵。殿侧两壁挂着几柄旧剑和一些青城派独门兵器，想来都是本派前辈名宿们当年斩妖除魔时所佩神兵，供奉于此激励后代弟子。]],["enterable"]=1,["id"]=[[fb08_34]],["item1"]=[[fb08item19]],["name"]=[[上清殿]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb08_36]],["visible"]=1},["fb08_35"]={["down"]=[[fb08_31]],["dsc"]=[[这是一间存放兵器的屋子。刀、枪、剑、戟等各种兵器都按类放在各自的兵器架上。整个屋子落满灰尘，显然已经好久没人来过。]],["enterable"]=1,["id"]=[[fb08_35]],["item1"]=[[fb08item11]],["item2"]=[[fb08item15]],["name"]=[[兵器室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb08_36"]={["down"]=[[fb08_34]],["dsc"]=[[这是松风观后的一个园子，庭院清幽，异种花卉甚是不少。此处高寒花卉也异平常，风姿倬约，煞是惹人怜爱。东面通往掌门人卧室，南面是三清殿。]],["enterable"]=1,["id"]=[[fb08_36]],["name"]=[[花园]],["permission"]=2,["right"]=[[fb08_37]],["role1"]=[[fb08r36_1]],["stepMusic"]=[[nidi]],["visible"]=1},["fb08_37"]={["BgmDown"]=1,["dsc"]=[[这里是余岳正的寝室。余岳正虽然是道家弟子，可也不禁婚约。因此他娶了正配，还一气陪进来好几个小妾。卧室中摆着一张楠木花雕大床，一具红松大衣柜，柜顶搁着几只牛皮藤箱子，墙角立着一张有点陈旧的梳妆台，靠窗处是一张花梨木书桌。]],["enterable"]=1,["id"]=[[fb08_37]],["item1"]=[[fb08item5]],["item2"]=[[fb08item22]],["left"]=[[fb08_36]],["name"]=[[卧室]],["permission"]=2,["role1"]=[[fb08r37_1]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb08_38"]={["down"]=[[fb08_40]],["dsc"]=[[这里是青城山中的蜘蛛巢，四面无光，伸手不见五指，脚下满是腥臭的淤泥。远方似闪烁着豆大绿光。]],["id"]=[[fb08_38]],["item1"]=[[fb08item30]],["item2"]=[[fb08item31]],["name"]=[[蜘蛛巢]],["permission"]=2,["role1"]=[[fb08r38_1]],["role2"]=[[fb08r38_2]],["roomBgm"]=[[jinzhang_incave]],["stepMusic"]=[[nidi]]},["fb08_39"]={["dsc"]=[[这里是青城山中的蜘蛛巢，四面无光，伸手不见五指，脚下满是腥臭的淤泥。远方似闪烁着豆大绿光。]],["id"]=[[fb08_39]],["item1"]=[[fb08item31]],["item2"]=[[fb08item32]],["name"]=[[蜘蛛巢]],["permission"]=2,["right"]=[[fb08_40]],["role1"]=[[fb08r39_1]],["roomBgm"]=[[jinzhang_incave]],["stepMusic"]=[[nidi]]},["fb08_40"]={["down"]=[[fb08_42]],["dsc"]=[[这里是青城山中的蜘蛛巢，四面无光，伸手不见五指，脚下满是腥臭的淤泥。远方似闪烁着豆大绿光。]],["id"]=[[fb08_40]],["item1"]=[[fb08item31]],["lef